//! IBM Model 1 with a diagonal positional prior, in the style of
//! `fast_align` (Dyer et al. 2013), trained in one direction.
//!
//! The model explains every "f" token of a sentence by one "e" token of
//! the paired sentence (or by the NULL word). Which side is "e" and which
//! is "f" is up to the caller, so the same trainer serves both directions.

/// Prior probability that an `f` token is generated by NULL.
const NULL_PROB: f32 = 0.08;

/// Relative positional window outside which an `(e, f)` pair is not even
/// considered. The diagonal prior makes far pairs negligible anyway, and
/// skipping them keeps the sparse table small on a whole Bible.
const WINDOW: f32 = 0.4;

/// Pairs accumulate in a buffer that is folded into the sorted key list at
/// this size, so the peak memory stays close to the number of distinct
/// pairs instead of the number of pair instances.
const FLUSH_AT: usize = 1 << 20;

/// Index of the NULL word on the `e` side of the table.
const NULL: u32 = 0;

/// Posterior summary for one `f` position.
#[derive(Debug, Clone, Default)]
pub(crate) struct Posterior {
    /// The `e` position with the highest posterior; `None` when NULL won.
    pub(crate) best: Option<u16>,
    /// Real `e` positions whose posterior reached the trainer threshold,
    /// highest first. Lets the symmetriser consider one-to-many links
    /// that the 1-best of either direction would hide.
    pub(crate) candidates: Vec<(u16, f32)>,
}

/// Sparse translation table `t(f | e)` stored row-major by `e` in CSR
/// form. Only pairs that co-occur inside the positional window exist.
struct Table {
    offsets: Vec<usize>,
    cols: Vec<u32>,
    t: Vec<f32>,
    counts: Vec<f32>,
    totals: Vec<f32>,
}

impl Table {
    fn build(e_sents: &[Vec<u32>], f_sents: &[Vec<u32>], e_vocab: u32) -> Self {
        let mut keys = KeySet::default();
        for (e, f) in e_sents.iter().zip(f_sents) {
            let (n, m) = (e.len(), f.len());
            if n == 0 || m == 0 {
                continue;
            }
            for (j, &fj) in f.iter().enumerate() {
                keys.push(pair_key(NULL, fj));
                for (i, &ei) in e.iter().enumerate() {
                    if in_window(i, n, j, m) {
                        keys.push(pair_key(ei + 1, fj));
                    }
                }
            }
        }
        let keys = keys.finish();
        let rows = e_vocab as usize + 1;
        let mut offsets = vec![0usize; rows + 1];
        for &k in &keys {
            offsets[(k >> 32) as usize + 1] += 1;
        }
        for r in 0..rows {
            offsets[r + 1] += offsets[r];
        }
        let cols = keys
            .iter()
            .map(|&k| u32::try_from(k & 0xFFFF_FFFF).unwrap_or(u32::MAX))
            .collect();
        let len = keys.len();
        Self {
            offsets,
            cols,
            t: vec![1.0; len],
            counts: vec![0.0; len],
            totals: vec![0.0; rows],
        }
    }

    fn index(&self, e: u32, f: u32) -> Option<usize> {
        let start = self.offsets[e as usize];
        let end = self.offsets[e as usize + 1];
        self.cols[start..end]
            .binary_search(&f)
            .ok()
            .map(|k| start + k)
    }

    fn maximize(&mut self) {
        for e in 0..self.totals.len() {
            let total = self.totals[e];
            if total <= 0.0 {
                continue;
            }
            for k in self.offsets[e]..self.offsets[e + 1] {
                self.t[k] = self.counts[k] / total;
            }
        }
        self.counts.fill(0.0);
        self.totals.fill(0.0);
    }
}

/// Deduplicating accumulator of `(e, f)` keys with bounded peak memory.
#[derive(Default)]
struct KeySet {
    sorted: Vec<u64>,
    buffer: Vec<u64>,
}

impl KeySet {
    fn push(&mut self, key: u64) {
        self.buffer.push(key);
        if self.buffer.len() >= FLUSH_AT {
            self.flush();
        }
    }

    fn flush(&mut self) {
        self.buffer.sort_unstable();
        self.buffer.dedup();
        self.sorted.append(&mut self.buffer);
        self.sorted.sort_unstable();
        self.sorted.dedup();
    }

    fn finish(mut self) -> Vec<u64> {
        self.flush();
        self.sorted
    }
}

fn pair_key(e: u32, f: u32) -> u64 {
    (u64::from(e) << 32) | u64::from(f)
}

#[allow(clippy::cast_precision_loss)]
fn relative_distance(i: usize, n: usize, j: usize, m: usize) -> f32 {
    ((i + 1) as f32 / n as f32 - (j + 1) as f32 / m as f32).abs()
}

fn in_window(i: usize, n: usize, j: usize, m: usize) -> bool {
    relative_distance(i, n, j, m) <= WINDOW
}

/// One-direction trainer: learns `t(f | e)` and returns, for every `f`
/// position of every sentence, the `e` position with the highest
/// posterior.
pub(crate) struct Trainer<'a> {
    e_sents: &'a [Vec<u32>],
    f_sents: &'a [Vec<u32>],
    tension: f32,
    min_prob: f32,
    table: Table,
    /// Scratch: candidate `(table index, e position, probability)` per `f`.
    scratch: Vec<(usize, u16, f32)>,
}

impl<'a> Trainer<'a> {
    pub(crate) fn new(
        e_sents: &'a [Vec<u32>],
        f_sents: &'a [Vec<u32>],
        e_vocab: u32,
        tension: f32,
        min_prob: f32,
    ) -> Self {
        debug_assert_eq!(e_sents.len(), f_sents.len());
        Self {
            e_sents,
            f_sents,
            tension,
            min_prob,
            table: Table::build(e_sents, f_sents, e_vocab),
            scratch: Vec::new(),
        }
    }

    /// Runs `iterations` rounds of EM and then decodes the best link per
    /// `f` position.
    pub(crate) fn run(mut self, iterations: u32) -> Vec<Vec<Posterior>> {
        for _ in 0..iterations {
            self.expectation(true);
            self.table.maximize();
        }
        self.expectation(false)
    }

    /// E-step over the corpus. With `accumulate` the expected counts are
    /// added to the table; the best link per `f` position is always
    /// returned so the last call doubles as the decoder.
    fn expectation(&mut self, accumulate: bool) -> Vec<Vec<Posterior>> {
        let mut best = Vec::with_capacity(self.f_sents.len());
        for (e, f) in self.e_sents.iter().zip(self.f_sents) {
            let (n, m) = (e.len(), f.len());
            let mut sentence = Vec::with_capacity(m);
            if n == 0 || m == 0 {
                best.push(sentence);
                continue;
            }
            for (j, &fj) in f.iter().enumerate() {
                sentence.push(self.posterior(e, fj, j, m, accumulate));
            }
            best.push(sentence);
        }
        best
    }

    /// Posterior over the `e` positions (plus NULL) for the `f` word `f_word`
    /// at position `f_pos` of an `f` sentence of length `f_len`: the argmax,
    /// and every real position above the threshold.
    fn posterior(
        &mut self,
        e_words: &[u32],
        f_word: u32,
        f_pos: usize,
        f_len: usize,
        accumulate: bool,
    ) -> Posterior {
        let e_len = e_words.len();
        self.scratch.clear();
        let mut prior_norm = 0.0f32;
        for e_pos in 0..e_len {
            prior_norm += (-self.tension * relative_distance(e_pos, e_len, f_pos, f_len)).exp();
        }
        let mut total = 0.0f32;
        if let Some(index) = self.table.index(NULL, f_word) {
            let score = NULL_PROB * self.table.t[index];
            self.scratch.push((index, u16::MAX, score));
            total += score;
        }
        for (e_pos, &e_word) in e_words.iter().enumerate() {
            if !in_window(e_pos, e_len, f_pos, f_len) {
                continue;
            }
            let Some(index) = self.table.index(e_word + 1, f_word) else {
                continue;
            };
            let distance = relative_distance(e_pos, e_len, f_pos, f_len);
            let prior = (1.0 - NULL_PROB) * (-self.tension * distance).exp() / prior_norm;
            let score = prior * self.table.t[index];
            let Ok(position) = u16::try_from(e_pos) else {
                continue;
            };
            self.scratch.push((index, position, score));
            total += score;
        }
        let mut result = Posterior::default();
        if total <= 0.0 {
            return result;
        }
        let mut winner_p = 0.0f32;
        for &(index, position, score) in &self.scratch {
            let post = score / total;
            if accumulate {
                self.table.counts[index] += post;
                let row = if position == u16::MAX {
                    NULL
                } else {
                    e_words[position as usize] + 1
                };
                self.table.totals[row as usize] += post;
            }
            if post > winner_p {
                winner_p = post;
                result.best = (position != u16::MAX).then_some(position);
            }
            if position != u16::MAX && post >= self.min_prob {
                result.candidates.push((position, post));
            }
        }
        result
            .candidates
            .sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        result
    }
}
